package com.fitnutri.backend.activity.catalogue;
import com.fitnutri.backend.activity.*;
import com.fitnutri.backend.common.BusinessException;
import com.fitnutri.backend.support.TestDatabase;
import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.core.io.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.*;
import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @ActiveProfiles("integration-test")
class ExerciseCatalogueImportIT {
 static final TestDatabase DB=TestDatabase.create();static{Runtime.getRuntime().addShutdownHook(new Thread(DB::close));}
 @DynamicPropertySource static void database(DynamicPropertyRegistry r){r.add("spring.datasource.url",DB::url);r.add("spring.datasource.username",DB::username);r.add("spring.datasource.password",DB::password);}
 @Autowired ActivityReferenceImportService official;@Autowired ExerciseOptionImporter products;@Autowired JdbcTemplate jdbc;
 void empty(){assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM exercise_option",Long.class));assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM movement_catalogue",Long.class));}
 String checksum(String revision){return jdbc.queryForObject("SELECT md5(string_agg(concat_ws('|',t.id,t.activity_key,t.source_activity_code,t.source_description,t.met_value),';' ORDER BY t.id)) FROM exercise_type t JOIN activity_dataset d ON d.id=t.dataset_id WHERE d.revision=?",String.class,revision);}
 @Test void realPinnedR2ImportPreservesR1AndCatalogueIsDryRunAtomicVersionedAndRepeatable()throws Exception{
  Path directory=Path.of(System.getenv().getOrDefault("TEST_REFERENCE_SOURCE_DIR",Path.of("..",".local","reference-sources").toString())).toAbsolutePath().normalize();Map<String,Resource> raw=new HashMap<>();for(String name:List.of("2024-adult-compendium.pdf","2024-adult-compendium-age-source.html"))raw.put(name,new FileSystemResource(directory.resolve(name)));
  official.importActivityManifest(new ClassPathResource("data/manifests/compendium-2024-r1.json"),new ClassPathResource("data/compendium-2024-activities-r1.json"),raw);String old=checksum("2025-02-pdf_representative-r1");official.importActivityManifest(new ClassPathResource("data/manifests/compendium-2024-r2.json"),new ClassPathResource("data/compendium-2024-activities-r2.json"),raw);assertEquals(old,checksum("2025-02-pdf_representative-r1"));assertEquals(15,jdbc.queryForObject("SELECT count(*) FROM exercise_type t JOIN activity_dataset d ON d.id=t.dataset_id WHERE d.revision='2025-02-pdf_representative-r1' AND NOT t.is_active",Long.class));assertEquals(26,jdbc.queryForObject("SELECT count(*) FROM exercise_type WHERE is_active",Long.class));String before=checksum("2025-02-pdf_ux-r2");
  var options=new ClassPathResource("data/ux/exercise-options-v1.json");var movements=new ClassPathResource("data/ux/movement-catalogue-v1.json");var dry=products.importImmutableCatalogueVersion(options,movements,true);assertTrue(dry.dryRun());assertEquals(38,dry.options());assertEquals(36,dry.movements());empty();
  jdbc.update("UPDATE exercise_type SET is_active=false WHERE activity_key='rowing' AND is_active");assertThrows(BusinessException.class,()->products.importImmutableCatalogueVersion(options,movements,false));empty();jdbc.update("UPDATE exercise_type SET is_active=true WHERE activity_key='rowing' AND dataset_id=(SELECT id FROM activity_dataset WHERE revision='2025-02-pdf_ux-r2')");
  String suffix=UUID.randomUUID().toString().replace("-","");String function="test_catalogue_fail_"+suffix,trigger="test_catalogue_trigger_"+suffix;jdbc.execute("CREATE FUNCTION "+function+"() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'Synthetic later catalogue rejection' USING ERRCODE='23514'; END$$");jdbc.execute("CREATE TRIGGER "+trigger+" BEFORE INSERT ON movement_catalogue FOR EACH ROW WHEN (NEW.movement_key='plank') EXECUTE FUNCTION "+function+"()");try{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->products.importImmutableCatalogueVersion(options,movements,false));empty();}finally{jdbc.execute("DROP TRIGGER "+trigger+" ON movement_catalogue");jdbc.execute("DROP FUNCTION "+function+"()");}
  var result=products.importImmutableCatalogueVersion(options,movements,false);assertEquals(38,result.options());assertEquals(36,result.movements());assertFalse(result.replayed());var replay=products.importImmutableCatalogueVersion(options,movements,false);assertTrue(replay.replayed());assertEquals(0,replay.options());assertEquals(0,replay.movements());assertEquals(before,checksum("2025-02-pdf_ux-r2"));assertEquals(old,checksum("2025-02-pdf_representative-r1"));assertEquals(36,jdbc.queryForObject("SELECT count(*) FROM movement_catalogue m JOIN exercise_option o ON o.id=m.default_period_option_id WHERE m.active AND o.active AND o.period_kind='STRENGTH' AND o.review_status='REVIEWED'",Long.class));var rower=jdbc.queryForMap("SELECT mapping_kind,reference_id FROM exercise_option WHERE option_key='rowing-machine'");assertEquals("UNAVAILABLE",rower.get("mapping_kind"));assertNull(rower.get("reference_id"));assertEquals("02071",jdbc.queryForObject("SELECT t.source_activity_code FROM exercise_option o JOIN exercise_type t ON t.id=o.reference_id WHERE o.option_key='rowing-under100w'",String.class));
  jdbc.update("UPDATE exercise_option SET active=false WHERE option_key='rowing-under100w'");assertTrue(products.importImmutableCatalogueVersion(options,movements,false).replayed());assertFalse(jdbc.queryForObject("SELECT active FROM exercise_option WHERE option_key='rowing-under100w'",Boolean.class));
  String database;try(var connection=DB.connect()){database=connection.getCatalog();}String container=System.getenv("TEST_DB_DOCKER_CONTAINER");assertNotNull(container);var process=new ProcessBuilder("python3",Path.of("..","scripts","preflight_ux_v3.py").toString(),"--container",container,"--user",DB.username(),"--database",database,"--source-dir",directory.toString()).redirectErrorStream(true).start();String output=new String(process.getInputStream().readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);assertTrue(process.waitFor(20,java.util.concurrent.TimeUnit.SECONDS));assertEquals(0,process.exitValue(),output);var preflight=new tools.jackson.databind.ObjectMapper().readTree(output);assertEquals("PASS",preflight.get("status").asText());assertTrue(preflight.get("readOnly").asBoolean());assertFalse(preflight.get("migrationApplied").asBoolean());assertEquals(before,checksum("2025-02-pdf_ux-r2"));assertEquals(old,checksum("2025-02-pdf_representative-r1"));

 }
}
